            panel_task_count = _G2048_PANEL_SPLITS * trailing_rows
            task_count = trailing_rows * (trailing_rows + 1)
            if task_count == 0:
                panel_launchers.append(None)
                update_launchers.append(None)
            else:
                panel_launchers.append(
                    _g2048_panel_dispatch[
                        batch * panel_task_count,
                        _G2048_NT,
                        queue,
                        _G2048_SHARED_BYTES,
                    ]
                )
                group_count = (
                    task_count + _G2048_UPDATES_PER_CTA - 1
                ) // _G2048_UPDATES_PER_CTA
                update_launchers.append(
                    _g2048_update_dispatch[
                        batch * group_count,
                        _G2048_NT,
                        queue,
                        _G2048_SHARED_BYTES,
                    ]
                )
        launchers = (
            queue,
            factor_launcher,
            first_factor_launcher,
            first_panel_launcher,
            tuple(panel_launchers),
            tuple(update_launchers),
        )
        _g2048_launcher_cache[key] = launchers
    return launchers[1:]


def _batch1024_factor_launcher_for_current_queue(
    factor_view, factor_half_view, flag_view, batch
):
    global _batch1024_factor_dispatch, _batch1024_factor_launcher
    global _batch1024_factor_queue_handle, _batch1024_factor_queue
    if _batch1024_factor_dispatch is None:
        _batch1024_factor_dispatch = _batch1024_factor_two_cta.specialize(
            factor_view,
            factor_view,
            factor_half_view,
            flag_view,
            np.int32(0),
        )
        compiled = next(
            iter(_batch1024_factor_dispatch.overloads.values())
        )
        function = compiled._codelibrary.get_cufunc()
        attribute = (
            cuda_driver.CUfunction_attribute.
            CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES
        )
        numba_driver.driver.cuKernelSetAttribute(
            attribute,
            _D256_SHARED_BYTES,
            function.handle,
            function.device.id,
        )
        carveout_attribute = (
            cuda_driver.CUfunction_attribute.
            CU_FUNC_ATTRIBUTE_PREFERRED_SHARED_MEMORY_CARVEOUT
        )
        numba_driver.driver.cuKernelSetAttribute(
            carveout_attribute,
            0,
            function.handle,
            function.device.id,
        )
    torch_queue = _torch_current_queue()
    queue_handle = getattr(torch_queue, _torch_queue_handle_name)
    if (
        queue_handle != _batch1024_factor_queue_handle
        or _batch1024_factor_launcher is None
    ):
        _batch1024_factor_queue = _external_queue(queue_handle)
        _batch1024_factor_queue_handle = queue_handle
        _batch1024_factor_launcher = _batch1024_factor_dispatch[
            batch * 2,
            _D256_NT,
            _batch1024_factor_queue,
            _D256_SHARED_BYTES,
        ]
    return _batch1024_factor_launcher


def _launch_batch1024_panel_dag(
    factor_view, factor_half_view, output_view, panel_groups, batch
):
    global _batch1024_panel_dispatch
    global _batch1024_panel_queue_handle, _batch1024_panel_queue
    if _batch1024_panel_dispatch is None:
        dispatches = []
        for solve_kernel, update_kernels in zip(
            (
                _batch1024_panel_solve_bulk,
                _batch1024_panel_solve_middle,
                _batch1024_panel_solve_tail,
            ),
            (
                (
                    _batch1024_panel_update1_bulk,
                    _batch1024_panel_update2_bulk,
                    _batch1024_panel_update3_bulk,
                ),
                (
                    _batch1024_panel_update1_middle,
                    _batch1024_panel_update2_middle,
                    _batch1024_panel_update3_middle,
                ),
                (
                    _batch1024_panel_update1_tail,
                    _batch1024_panel_update2_tail,
                    _batch1024_panel_update3_tail,
                ),
            ),
        ):
            stage_dispatches = []
            for kernel_index, kernel in enumerate(
                (solve_kernel, *update_kernels)
            ):
                shared_bytes = (
                    _B1024_SOLVE_SHARED_BYTES
                    if kernel_index == 0
                    else _B1024_UPDATE_SHARED_BYTES
                )
                if kernel_index == 0:
                    dispatch = kernel.specialize(
                        factor_view, output_view, np.int32(0)
                    )
                else:
                    dispatch = kernel.specialize(
                        factor_half_view, output_view
                    )
                compiled = next(iter(dispatch.overloads.values()))
                function = compiled._codelibrary.get_cufunc()
                attribute = (
                    cuda_driver.CUfunction_attribute.
                    CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES
                )
                numba_driver.driver.cuKernelSetAttribute(
                    attribute,
                    shared_bytes,
                    function.handle,
                    function.device.id,
                )
                carveout_attribute = (
                    cuda_driver.CUfunction_attribute.
                    CU_FUNC_ATTRIBUTE_PREFERRED_SHARED_MEMORY_CARVEOUT
                )
                numba_driver.driver.cuKernelSetAttribute(
                    carveout_attribute,
                    100,
                    function.handle,
                    function.device.id,
                )
                stage_dispatches.append(dispatch)
            dispatches.append(
                (stage_dispatches[0], tuple(stage_dispatches[1:]))
            )
        _batch1024_panel_dispatch = tuple(dispatches)
    torch_queue = _torch_current_queue()
    queue_handle = getattr(torch_queue, _torch_queue_handle_name)
    if queue_handle != _batch1024_panel_queue_handle:
        _batch1024_panel_queue = _external_queue(queue_handle)
        _batch1024_panel_queue_handle = queue_handle
    solve_dispatch, update_dispatches = _batch1024_panel_dispatch[
        (12 - panel_groups) // 4
    ]
    solve_launcher = solve_dispatch[
        (panel_groups, batch),
        _B1024_NT,
        _batch1024_panel_queue,
        _B1024_SOLVE_SHARED_BYTES,
    ]
    solve_launcher(factor_view, output_view, np.int32(0))
    for current_tile, update_dispatch in enumerate(
        update_dispatches, start=1
    ):
        tile = np.int32(current_tile)
        update_dispatch[
            (panel_groups, batch),
            _B1024_NT,
            _batch1024_panel_queue,
            _B1024_UPDATE_SHARED_BYTES,
        ](factor_half_view, output_view)
        solve_launcher(factor_view, output_view, tile)


def _grouped_mathdx_cholesky(
    data: torch.Tensor,
    output: torch.Tensor,
    source_view,
    output_view,
) -> torch.Tensor:
    n = output.shape[-1]
    block = _G2048_N
    key = id(output)
    stage_entry = _g2048_stage_cache.get(key)
    if stage_entry is None or stage_entry[0] is not output:
        sample_chains = []
        first_panel_ctas = (
            148
            if (output.shape[0], n) in ((4, 1024), (2, 2048))
            else _G2048_FIRST_PANEL_CTAS
        )
        for sample in range(output.shape[0]):
            sample_input = data[sample : sample + 1]
            sample_output = output[sample : sample + 1]
            stages = []
            for panel_index, panel_origin in enumerate(range(0, n, block)):
                stop = panel_origin + block
                launch_args = (
                    np.int64(n),
                    np.int64(n * n),
                    np.int64(panel_origin),
                )
                if stop == n:
                    stages.append((launch_args, panel_index, None))
                    continue
                panel = sample_output[:, panel_origin:stop, stop:]
                trailing_input = sample_input[:, stop:, stop:]
                trailing_output = sample_output[:, stop:, stop:]
                panel_pointer = cute_runtime.make_ptr(
                    cutlass.Float32,
                    panel.data_ptr(),
                    cute.AddressSpace.gmem,
                    assumed_align=16,
                )
                output_pointer = cute_runtime.make_ptr(
                    cutlass.Float32,
                    trailing_output.data_ptr(),
                    cute.AddressSpace.gmem,
                    assumed_align=16,
                )
                accumulator_pointer = (
                    cute_runtime.make_ptr(
                        cutlass.Float32,
                        trailing_input.data_ptr(),
                        cute.AddressSpace.gmem,
                        assumed_align=16,
                    )
                    if panel_index == 0
                    else output_pointer
                )
                rankk_stage = (
                    panel,
                    trailing_input,
                    trailing_output,
                    panel_pointer,
                    accumulator_pointer,
                    output_pointer,
                    (
                        cutlass.Int32(n - stop),
                        cutlass.Int32(block),
                        cutlass.Int32(1),
                        cutlass.Int32(sample_output.stride(0)),
                        cutlass.Int32(sample_output.stride(1)),
                        cutlass.Int32(sample_output.stride(0)),
                    ),
                )
                stages.append((launch_args, panel_index, rankk_stage))
            sample_chains.append(
                (
                    np.int32(sample),
                    sample_output,
                    tuple(stages),
                    first_panel_ctas,
                )
            )
        queues = tuple(
            _TorchQueue(priority=0) for _ in sample_chains
        )
        start_event = torch.cuda.Event()
        done_events = tuple(torch.cuda.Event() for _ in sample_chains)
        release_events = tuple(
            torch.cuda.Event() for _ in range(len(sample_chains) // 2)
        )
        stage_entry = [
            output,
            tuple(sample_chains),
            queues,
            start_event,
            done_events,
            release_events,
            None,
        ]
        _g2048_stage_cache[key] = stage_entry
    graph = stage_entry[6]
    if graph is None:
        _compute_g2048_graph(
            source_view,
            output_view,
            stage_entry[1],
            stage_entry[2],
            stage_entry[3],
            stage_entry[4],
            stage_entry[5],
        )
        graph = torch.cuda.CUDAGraph()
        with torch.cuda.graph(graph):
            _compute_g2048_graph(
                source_view,
                output_view,
                stage_entry[1],
                stage_entry[2],
                stage_entry[3],
                stage_entry[4],
                stage_entry[5],
            )
        stage_entry[6] = graph
    graph.replay()
    return output.transpose(-2, -1)


def _compute_g2048_sample_chain(
    source_view,
    output_view,
    sample_index,
    sample_output,
    stages,
    first_panel_ctas,
    release_event,
) -> None:
    (
        factor_launcher,
        first_factor_launcher,
        first_panel_launcher,
        panel_launchers,
        update_launchers,
    ) = (
        _g2048_launchers_for_current_queue(
            source_view, output_view, 1, first_panel_ctas
        )
    )
    tile_count = _G2048_N // _G2048_NB
    for launch_args, panel_index, rankk_stage in stages:
        for tile in range(tile_count):
            tile_value = np.int32(tile)
            first_wave = panel_index == 0 and tile == 0
            if first_wave:
                factor_launch_count = (
                    first_panel_ctas
                    - _G2048_PANEL_SPLITS * (tile_count - 1)
                    + 1
                )
                first_factor_launcher(
                    source_view,
                    output_view,
                    launch_args[0],
                    launch_args[1],
                    sample_index,
                    np.int32(factor_launch_count),
                )
            else:
                factor_launcher(
                    source_view,
                    output_view,
                    *launch_args,
                    tile_value,
                    sample_index,
                )
            if (
                release_event is not None
                and panel_index == 0
                and tile == 0
            ):
                release_event.record()
            if tile + 1 < tile_count:
                trailing_rows = tile_count - tile - 1
                panel_task_count = _G2048_PANEL_SPLITS * trailing_rows
                panel_launcher = (
                    first_panel_launcher
                    if first_wave
                    else panel_launchers[tile]
                )
                panel_launcher(
                    source_view,
                    output_view,
                    *launch_args,
                    tile_value,
                    np.int32(panel_task_count),
                    np.int32(panel_task_count),
                    sample_index,
                )
                task_count = trailing_rows * (trailing_rows + 1)
                update_launchers[tile](
                    source_view,
                    output_view,
                    *launch_args,
                    tile_value,
                    np.int32(task_count),
                    sample_index,
                )
        _ext.grouped_panel_update_one_(
            sample_output, _G2048_N, panel_index
        )
        if rankk_stage is not None:
            _g2048_triangular_rankk_(
                rankk_stage[3],
                rankk_stage[4],
                rankk_stage[5],
                rankk_stage[6],
            )


def _compute_g2048_graph(
    source_view,
    output_view,
    sample_chains,
    queues,
    start_event,
    done_events,
    release_events,
) -> None:
    origin = _torch_current_queue()
    start_event.record(origin)
    split = (len(queues) + 1) // 2
    for queue in queues[:split]:
        start_event.wait(queue)
    for chain_index, (chain, queue, done_event) in enumerate(zip(
        sample_chains[:split],
        queues[:split],
        done_events[:split],
    )):
        release_event = (
            release_events[chain_index]
            if chain_index < len(release_events)
            else None
        )
        with _torch_queue_context(queue):
            _compute_g2048_sample_chain(
                source_view, output_view, *chain, release_event
            )
            done_event.record(queue)
    for chain, queue, done_event, release_event in zip(
        sample_chains[split:],
        queues[split:],
        done_events[split:],
        release_events,
    ):
        release_event.wait(queue)
        with _torch_queue_context(queue):
            _compute_g2048_sample_chain(
                source_view, output_view, *chain, None
            )
            done_event.record(queue)
    for done_event in done_events:
        done_event.wait(origin)


